package com.example.workout.workout.mapper; import com.example.workout.generated.model.*; import com.example.workout.workout.model.*; public final class WorkoutMapperAccess { private WorkoutMapperAccess(){throw new UnsupportedOperationException("This class should never be instantiated");} static WorkoutSegment segment(WorkoutSegmentRequest x){return WorkoutSegment.builder().withPosition(x.getPosition()).withSegmentType(WorkoutSegmentType.valueOf(x.getSegmentType().getValue())).withName(x.getName()).withRepetitions(x.getRepetitions()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).withRestDistanceMeters(x.getRestDistanceMeters()).withRestDurationSeconds(x.getRestDurationSeconds()).build();} static WorkoutLap lap(WorkoutLapRequest x){return WorkoutLap.builder().withPosition(x.getPosition()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).build();} static WorkoutTrackPoint point(WorkoutTrackPointRequest x){return WorkoutTrackPoint.builder().withPosition(x.getPosition()).withRecordedAt(x.getRecordedAt()).withLatitude(x.getLatitude()).withLongitude(x.getLongitude()).build();} }
